const imgVariantOffSizeLgStateDefault = "https://www.figma.com/api/mcp/asset/32aa3210-0d26-417a-8851-7eb355f076c6.svg";

type SwitchProps = {
  className?: string;
  size?: "lg";
  state?: "default";
  variant?: "off";
