/* =================================================================
   Atlas Switch — component styles
   All values reference semantic tokens only.
   No hex literals. No magic numbers. Logical properties throughout.
   ================================================================= */

/* ── Root wrapper ─────────────────────────────────────────────── */

.root {
  display: inline-flex;
  align-items: flex-start;
  gap: var(--atlas-spacing-3);
}

.root[data-disabled] {
  opacity: var(--atlas-opacity-disabled);
  cursor: not-allowed;
}

/* ── Track (the <button>) ─────────────────────────────────────── */

.track {
  flex-shrink: 0;
  border: none;
  padding: 0;
  border-radius: var(--atlas-radius-full);
  background-color: var(--atlas-background-muted); /* off state per spec */
  position: relative;
  cursor: pointer;
  outline: none;
  transition:
    background-color var(--atlas-duration-fast) var(--atlas-easing-standard);
}

.track[data-state="checked"] {
  background-color: var(--atlas-primary);
}

/* ── Hover states ─────────────────────────────────────────────── */

.track:hover:not([data-disabled])[data-state="unchecked"] {
  background-color: var(--atlas-background-subtle);
}

.track:hover:not([data-disabled])[data-state="checked"] {
  background-color: var(--atlas-primary-hover);
}

/*
  BUG-053 — dark mode inversion fix.
  In dark mode the background scale runs: background (neutral-950) →
  background-subtle (neutral-900) → background-muted (neutral-800, lightest).
  The resting unchecked track is background-muted (lightest) so hovering
  to background-subtle (darker) creates an inverted affordance.
  Override: lighten the resting colour slightly using color-mix instead of
  stepping toward a darker token.
*/
[data-theme="dark"] .track:hover:not([data-disabled])[data-state="unchecked"] {
  background-color: color-mix(in oklch, var(--atlas-background-muted) 80%, oklch(1 0 0));
}

/* ── Active / pressed state ───────────────────────────────────── */
/*
  BUG-020 — add :active pressed feedback for spec state matrix completeness.
  Unchecked active: matches hover token (sufficient feedback for the brief press).
  Checked active: one step deeper than hover.
*/

.track:active:not([data-disabled])[data-state="unchecked"] {
  background-color: var(--atlas-background-subtle);
}

.track:active:not([data-disabled])[data-state="checked"] {
  background-color: var(--atlas-primary-active);
}

[data-theme="dark"] .track:active:not([data-disabled])[data-state="unchecked"] {
  background-color: color-mix(in oklch, var(--atlas-background-muted) 70%, oklch(1 0 0));
}

.track[data-disabled] {
  cursor: not-allowed;
  pointer-events: none;
}

.track:focus-visible {
  outline: var(--atlas-border-width-2) solid var(--atlas-focus-ring);
  outline-offset: var(--atlas-spacing-0_5);
}

/* ── Touch target expansion (BUG-060) ────────────────────────── */
/*
  The visual track is 18px (sm) or 24px (md) — both below the 44px
  minimum touch target. On coarse-pointer (touchscreen) devices we
  expand the hit area via min-height and centre the track visually
  within the tappable region using align-items and display:flex.
  The wrapper .root is already inline-flex so this adds no layout cost.
*/

@media (pointer: coarse) {
  .track {
    min-height: var(--atlas-touch-min); /* 44 px tap target */
    display: flex;
    align-items: center;
  }
}

/* ── Sizes ────────────────────────────────────────────────────── */
/*
  Spec:
    sm: 32 × 18 px   thumb: 14 × 14 px   checked translate: 14 px
    md: 40 × 24 px   thumb: 20 × 20 px   checked translate: 16 px
    lg: 48 × 30 px   thumb: 26 × 26 px   checked translate: 18 px

  Token map:
    --atlas-spacing-8      = 32 px  (sm track width)
    --atlas-spacing-10     = 40 px  (md track width)
    --atlas-spacing-12     = 48 px  (lg track width)
    --atlas-spacing-6      = 24 px  (md track height)
    18 px = spacing-4(16) + spacing-0_5(2) = calc
    14 px = spacing-3(12) + spacing-0_5(2) = calc  (sm thumb + sm translate)
    --atlas-spacing-5      = 20 px  (md thumb)
    --atlas-spacing-4      = 16 px  (md checked translate)
    30 px = spacing-6(24) + spacing-1_5(6) = calc  (lg track height)
    26 px = spacing-5(20) + spacing-1_5(6) = calc  (lg thumb)
    --atlas-spacing-0_5    = 2 px   (inset on each side)
*/

.sm {
  width: var(--atlas-spacing-8);                                    /* 32 px */
  height: calc(var(--atlas-spacing-4) + var(--atlas-spacing-0_5)); /* 18 px */
}

.md {
  width: var(--atlas-spacing-10); /* 40 px */
  height: var(--atlas-spacing-6); /* 24 px */
}

.lg {
  width: var(--atlas-spacing-12);                                     /* 48 px */
  height: calc(var(--atlas-spacing-6) + var(--atlas-spacing-1_5));   /* 30 px */
}

/* ── Thumb ────────────────────────────────────────────────────── */

.thumb {
  display: block;
  position: absolute;
  border-radius: var(--atlas-radius-full);
  /*
   * BUG-019 — spec lists --atlas-background for thumb fill. However
   * --atlas-background resolves to neutral-950 in dark mode (near-black),
   * which would render as a dark thumb on a dark track — visually broken.
   * --atlas-foreground-on-brand = neutral-0 (pure white) in BOTH light and
   * dark themes, making it the correct semantic choice for a thumb that must
   * always appear as a white circle. This is a documented spec deviation.
   */
  background-color: var(--atlas-foreground-on-brand);
  box-shadow: var(--atlas-shadow-sm);
  /* Logical inset — RTL-safe starting position */
  inset-block-start: var(--atlas-spacing-0_5);
  inset-inline-start: var(--atlas-spacing-0_5);
  /* Spec: thumb glide uses duration-base + easing-emphasized */
  transition: transform var(--atlas-duration-base) var(--atlas-easing-emphasized);
}

.sm .thumb {
  /* 14 px = spacing-3(12) + spacing-0_5(2) */
  width: calc(var(--atlas-spacing-3) + var(--atlas-spacing-0_5));
  height: calc(var(--atlas-spacing-3) + var(--atlas-spacing-0_5));
}

.md .thumb {
  width: var(--atlas-spacing-5);  /* 20 px */
  height: var(--atlas-spacing-5); /* 20 px */
}

/*
  Checked — slide thumb toward inline-end.
  translate = track-width − thumb-width − 2×inset
  sm: 32 − 14 − 4 = 14 px = calc(spacing-3 + spacing-0_5)
  md: 40 − 20 − 4 = 16 px = spacing-4
*/
.sm[data-state="checked"] .thumb {
  transform: translateX(calc(var(--atlas-spacing-3) + var(--atlas-spacing-0_5)));
}

.md[data-state="checked"] .thumb {
  transform: translateX(var(--atlas-spacing-4));
}

/* RTL — negate the translate */
[dir="rtl"] .sm[data-state="checked"] .thumb {
  transform: translateX(calc(-1 * (var(--atlas-spacing-3) + var(--atlas-spacing-0_5))));
}

[dir="rtl"] .md[data-state="checked"] .thumb {
  transform: translateX(calc(-1 * var(--atlas-spacing-4)));
}

/* ── Reduced motion ───────────────────────────────────────────── */

@media (prefers-reduced-motion: reduce) {
  .track,
  .thumb {
    transition: none;
  }
}

/* ── Label + description ──────────────────────────────────────── */

.content {
  display: flex;
  flex-direction: column;
  gap: var(--atlas-spacing-1);
}

.label {
  font-family: var(--atlas-font-sans);
  font-size: var(--atlas-font-size-sm);
  font-weight: var(--atlas-font-weight-medium);
  color: var(--atlas-foreground);
  /* BUG-017 — was magic number 1.4 */
  line-height: var(--atlas-line-height-snug);
  cursor: pointer;
}

.root[data-disabled] .label {
  cursor: not-allowed;
}

.description {
  font-family: var(--atlas-font-sans);
  font-size: var(--atlas-font-size-xs);
  color: var(--atlas-foreground-muted);
  /* BUG-017 — was magic number 1.4 */
  line-height: var(--atlas-line-height-snug);
}

import figma from "@figma/code-connect"
import { Switch } from "@atlas/ui-web/primitives/Switch/Switch"

figma.connect(
  Switch,
  "https://www.figma.com/design/cKYhfaHLCoyMHi9nKr63Ig/Atlas-Design-System?node-id=95-114",
  {
    props: {
      defaultChecked: figma.enum("Variant", { off: false, on: true }),
      size:           figma.enum("Size",    { sm: "sm", md: "md" }),
      disabled:       figma.enum("State",   { disabled: true }),
    },
    example: ({ defaultChecked, size, disabled }) => (
      <Switch
        defaultChecked={defaultChecked}
        size={size}
        disabled={disabled}
        label="Switch label"
      />
    ),
  }
)

/**
 * Atlas Switch — test suite
 *
 * Coverage:
 *   1. Renders default, role=switch + aria-checked
 *   2. Size matrix — sm, md
 *   3. Keyboard activation — Space and Enter toggle; click toggles
 *   4. Focus-visible ring on the track
 *   5. Disabled state — blocks interaction, aria-disabled set
 *   6. Invalid state — aria-invalid set
 *   7. Controlled vs uncontrolled checked
 *   8. axe accessibility check
 *
 * Pattern: packages/ui-web/tests/Button.test.tsx
 */

import React from "react"
import { describe, it, expect, vi } from "vitest"
import { render, screen, fireEvent } from "@testing-library/react"
import { axe } from "jest-axe"
import { Switch, type SwitchSize } from "@atlas/ui-web/primitives/Switch/Switch"

// ─── Fixtures ──────────────────────────────────────────────────────────────

const SIZES: SwitchSize[] = ["sm", "md"]

// ─── 1. Default render ─────────────────────────────────────────────────────

describe("Switch — default render", () => {
  it("renders role=switch with aria-checked=false by default", () => {
    render(<Switch label="Push notifications" />)
    const el = screen.getByRole("switch", { name: /push notifications/i })
    expect(el).toHaveAttribute("aria-checked", "false")
  })

  it("renders aria-checked=true when defaultChecked", () => {
    render(<Switch label="Push notifications" defaultChecked />)
    expect(screen.getByRole("switch")).toHaveAttribute("aria-checked", "true")
  })
})

// ─── 2. Size matrix ─────────────────────────────────────────────────────

describe("Switch — size matrix", () => {
  for (const size of SIZES) {
    it(`renders size="${size}"`, () => {
      render(<Switch size={size} label={`${size} switch`} />)
      expect(screen.getByRole("switch", { name: new RegExp(`${size} switch`, "i") })).toBeInTheDocument()
    })
  }
})

// ─── 3. Keyboard + click activation ────────────────────────────────────────

describe("Switch — keyboard and click activation", () => {
  it("toggles on click", () => {
    const onCheckedChange = vi.fn()
    render(<Switch label="Wi-Fi" onCheckedChange={onCheckedChange} />)
    fireEvent.click(screen.getByRole("switch"))
    expect(onCheckedChange).toHaveBeenCalledWith(true)
  })

  // Space/Enter activation comes from the native <button>; jsdom does not synthesise the
  // key→click, so these assert the preconditions rather than simulate the keys.
  it("is type=button, so Space/Enter activate it and it never submits a form", () => {
    const onSubmit = vi.fn((e: React.FormEvent) => e.preventDefault())
    render(<form onSubmit={onSubmit}><Switch label="Wi-Fi" /></form>)
    const el = screen.getByRole("switch")
    expect(el).toHaveAttribute("type", "button")
    fireEvent.click(el)
    expect(onSubmit).not.toHaveBeenCalled()
  })

  it("toggles back off on a second click", () => {
    const onCheckedChange = vi.fn()
    render(<Switch label="Wi-Fi" onCheckedChange={onCheckedChange} />)
    const el = screen.getByRole("switch")
    fireEvent.click(el)
    fireEvent.click(el)
    expect(onCheckedChange).toHaveBeenLastCalledWith(false)
    expect(el).toHaveAttribute("aria-checked", "false")
  })

  it("is a native <button> so it receives keyboard focus in the tab order", () => {
    render(<Switch label="Wi-Fi" />)
    expect(screen.getByRole("switch").tagName).toBe("BUTTON")
  })
})

// ─── 4. Focus-visible ring ─────────────────────────────────────────────────

describe("Switch — focus", () => {
  it("can receive programmatic focus on the track element", () => {
    render(<Switch label="Wi-Fi" />)
    const el = screen.getByRole("switch")
    el.focus()
    expect(el).toHaveFocus()
  })
})

// ─── 5. Disabled state ──────────────────────────────────────────────────

describe("Switch — disabled state", () => {
  it("sets aria-disabled=true when disabled", () => {
    render(<Switch label="Wi-Fi" disabled />)
    expect(screen.getByRole("switch")).toHaveAttribute("aria-disabled", "true")
  })

  it("does not fire onCheckedChange when disabled", () => {
    const onCheckedChange = vi.fn()
    render(<Switch label="Wi-Fi" disabled onCheckedChange={onCheckedChange} />)
    fireEvent.click(screen.getByRole("switch"))
    expect(onCheckedChange).not.toHaveBeenCalled()
  })
})

// ─── 6. Invalid state ───────────────────────────────────────────────────

describe("Switch — invalid state", () => {
  it("sets aria-invalid=true when invalid", () => {
    render(<Switch label="Wi-Fi" invalid />)
    expect(screen.getByRole("switch")).toHaveAttribute("aria-invalid", "true")
  })

  it("does not set aria-invalid by default", () => {
    render(<Switch label="Wi-Fi" />)
    expect(screen.getByRole("switch")).not.toHaveAttribute("aria-invalid")
  })
})

// ─── 7. Controlled vs uncontrolled ──────────────────────────────────────

describe("Switch — controlled vs uncontrolled", () => {
  it("respects a controlled checked prop and does not flip internally", () => {
    const onCheckedChange = vi.fn()
    render(<Switch label="Wi-Fi" checked={false} onCheckedChange={onCheckedChange} />)
    const el = screen.getByRole("switch")
    fireEvent.click(el)
    expect(onCheckedChange).toHaveBeenCalledWith(true)
    // controlled: prop unchanged, so aria-checked stays false until parent re-renders
    expect(el).toHaveAttribute("aria-checked", "false")
  })

  it("flips internal state when uncontrolled", () => {
    render(<Switch label="Wi-Fi" />)
    const el = screen.getByRole("switch")
    fireEvent.click(el)
    expect(el).toHaveAttribute("aria-checked", "true")
  })
})

// ─── 8. axe accessibility ───────────────────────────────────────────────

describe("Switch — a11y (axe)", () => {
  it("passes axe unchecked", async () => {
    const { container } = render(<Switch label="Push notifications" />)
    expect(await axe(container)).toHaveNoViolations()
  })

  it("passes axe checked", async () => {
    const { container } = render(<Switch label="Push notifications" defaultChecked />)
    expect(await axe(container)).toHaveNoViolations()
  })

  it("passes axe disabled", async () => {
    const { container } = render(<Switch label="Push notifications" disabled />)
    expect(await axe(container)).toHaveNoViolations()
  })

  it("passes axe with description", async () => {
    const { container } = render(
      <Switch label="Push notifications" description="Alerts on this device" />
    )
    expect(await axe(container)).toHaveNoViolations()
  })

  it("warns in dev when no accessible name is provided", () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {})
    render(<Switch />)
    expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining("No accessible name provided"))
    warnSpy.mockRestore()
  })
})

/**
 * Atlas Switch — test suite
 *
 * Coverage:
 *   1. Renders default, role=switch + aria-checked
 *   2. Size matrix — sm, md, lg
 *   3. Keyboard activation — Space and Enter toggle; click toggles
 *   4. Focus-visible ring on the track
 *   5. Disabled state — blocks interaction, aria-disabled set
 *   6. Invalid state — aria-invalid set
 *   7. Controlled vs uncontrolled checked
 *   8. axe accessibility check
 *
 * Pattern: packages/ui-web/tests/Button.test.tsx
 */

import React from "react"
import { describe, it, expect, vi } from "vitest"
import { render, screen, fireEvent } from "@testing-library/react"
import { axe } from "jest-axe"
import { Switch, type SwitchSize } from "@atlas/ui-web/primitives/Switch/Switch"

// ─── Fixtures ──────────────────────────────────────────────────────────────

const SIZES: SwitchSize[] = ["sm", "md"]

// ─── 1. Default render ─────────────────────────────────────────────────────

describe("Switch — default render", () => {
  it("renders role=switch with aria-checked=false by default", () => {
    render(<Switch label="Push notifications" />)
    const el = screen.getByRole("switch", { name: /push notifications/i })
    expect(el).toHaveAttribute("aria-checked", "false")
  })

  it("renders aria-checked=true when defaultChecked", () => {
    render(<Switch label="Push notifications" defaultChecked />)
    expect(screen.getByRole("switch")).toHaveAttribute("aria-checked", "true")
  })
})

// ─── 2. Size matrix ─────────────────────────────────────────────────────

describe("Switch — size matrix", () => {
  for (const size of SIZES) {
    it(`renders size="${size}"`, () => {
      render(<Switch size={size} label={`${size} switch`} />)
      expect(screen.getByRole("switch", { name: new RegExp(`${size} switch`, "i") })).toBeInTheDocument()
    })
  }
})

// ─── 3. Keyboard + click activation ────────────────────────────────────────

describe("Switch — keyboard and click activation", () => {
  it("toggles on click", () => {
    const onCheckedChange = vi.fn()
    render(<Switch label="Wi-Fi" onCheckedChange={onCheckedChange} />)
    fireEvent.click(screen.getByRole("switch"))
    expect(onCheckedChange).toHaveBeenCalledWith(true)
  })

  // Space/Enter activation comes from the native <button>; jsdom does not synthesise the
  // key→click, so these assert the preconditions rather than simulate the keys.
  it("is type=button, so Space/Enter activate it and it never submits a form", () => {
    const onSubmit = vi.fn((e: React.FormEvent) => e.preventDefault())
    render(<form onSubmit={onSubmit}><Switch label="Wi-Fi" /></form>)
    const el = screen.getByRole("switch")
    expect(el).toHaveAttribute("type", "button")
    fireEvent.click(el)
    expect(onSubmit).not.toHaveBeenCalled()
  })

  it("toggles back off on a second click", () => {
    const onCheckedChange = vi.fn()
    render(<Switch label="Wi-Fi" onCheckedChange={onCheckedChange} />)
    const el = screen.getByRole("switch")
    fireEvent.click(el)
    fireEvent.click(el)
    expect(onCheckedChange).toHaveBeenLastCalledWith(false)
    expect(el).toHaveAttribute("aria-checked", "false")
  })

  it("is a native <button> so it receives keyboard focus in the tab order", () => {
    render(<Switch label="Wi-Fi" />)
    expect(screen.getByRole("switch").tagName).toBe("BUTTON")
  })
})

// ─── 4. Focus-visible ring ─────────────────────────────────────────────────

describe("Switch — focus", () => {
  it("can receive programmatic focus on the track element", () => {
    render(<Switch label="Wi-Fi" />)
    const el = screen.getByRole("switch")
    el.focus()
    expect(el).toHaveFocus()
  })
})

// ─── 5. Disabled state ──────────────────────────────────────────────────

describe("Switch — disabled state", () => {
  it("sets aria-disabled=true when disabled", () => {
    render(<Switch label="Wi-Fi" disabled />)
    expect(screen.getByRole("switch")).toHaveAttribute("aria-disabled", "true")
  })

  it("does not fire onCheckedChange when disabled", () => {
    const onCheckedChange = vi.fn()
    render(<Switch label="Wi-Fi" disabled onCheckedChange={onCheckedChange} />)
    fireEvent.click(screen.getByRole("switch"))
    expect(onCheckedChange).not.toHaveBeenCalled()
  })
})

// ─── 6. Invalid state ───────────────────────────────────────────────────

describe("Switch — invalid state", () => {
  it("sets aria-invalid=true when invalid", () => {
    render(<Switch label="Wi-Fi" invalid />)
    expect(screen.getByRole("switch")).toHaveAttribute("aria-invalid", "true")
  })

  it("does not set aria-invalid by default", () => {
    render(<Switch label="Wi-Fi" />)
    expect(screen.getByRole("switch")).not.toHaveAttribute("aria-invalid")
  })
})

// ─── 7. Controlled vs uncontrolled ──────────────────────────────────────

describe("Switch — controlled vs uncontrolled", () => {
  it("respects a controlled checked prop and does not flip internally", () => {
    const onCheckedChange = vi.fn()
    render(<Switch label="Wi-Fi" checked={false} onCheckedChange={onCheckedChange} />)
    const el = screen.getByRole("switch")
    fireEvent.click(el)
    expect(onCheckedChange).toHaveBeenCalledWith(true)
    // controlled: prop unchanged, so aria-checked stays false until parent re-renders
    expect(el).toHaveAttribute("aria-checked", "false")
  })

  it("flips internal state when uncontrolled", () => {
    render(<Switch label="Wi-Fi" />)
    const el = screen.getByRole("switch")
    fireEvent.click(el)
    expect(el).toHaveAttribute("aria-checked", "true")
  })
})

// ─── 8. axe accessibility ───────────────────────────────────────────────

describe("Switch — a11y (axe)", () => {
  it("passes axe unchecked", async () => {
    const { container } = render(<Switch label="Push notifications" />)
    expect(await axe(container)).toHaveNoViolations()
  })

  it("passes axe checked", async () => {
    const { container } = render(<Switch label="Push notifications" defaultChecked />)
    expect(await axe(container)).toHaveNoViolations()
  })

  it("passes axe disabled", async () => {
    const { container } = render(<Switch label="Push notifications" disabled />)
    expect(await axe(container)).toHaveNoViolations()
  })

  it("passes axe with description", async () => {
    const { container } = render(
      <Switch label="Push notifications" description="Alerts on this device" />
    )
    expect(await axe(container)).toHaveNoViolations()
  })

  it("warns in dev when no accessible name is provided", () => {
    const warnSpy = vi.spyOn(console, "warn").mockImplementation(() => {})
    render(<Switch />)
    expect(warnSpy).toHaveBeenCalledWith(expect.stringContaining("No accessible name provided"))
    warnSpy.mockRestore()
  })
})

